const els={kpiGrid:document.querySelector('#kpiGrid'),indexTitle:document.querySelector('#indexTitle'),indexValue:document.querySelector('#indexValue'),indexDelta:document.querySelector('#indexDelta'),indexChart:document.querySelector('#indexChart'),volumeTitle:document.querySelector('#volumeTitle'),volumeBadge:document.querySelector('#volumeBadge'),volumeValue:document.querySelector('#volumeValue'),volumeSub:document.querySelector('#volumeSub'),volumeChart:document.querySelector('#volumeChart'),volumeNote:document.querySelector('#volumeNote'),gauge:document.querySelector('#gauge'),gaugeValue:document.querySelector('#gaugeValue'),gaugeHeadline:document.querySelector('#gaugeHeadline'),gaugeText:document.querySelector('#gaugeText'),tradeRank:document.querySelector('#tradeRank'),unitRank:document.querySelector('#unitRank'),tradeRankTitle:document.querySelector('#tradeRankTitle'),unitRankTitle:document.querySelector('#unitRankTitle'),tradeRankUnit:document.querySelector('#tradeRankUnit'),unitRankUnit:document.querySelector('#unitRankUnit'),marketSummary:document.querySelector('#marketSummary'),asOf:document.querySelector('#asOf'),contextLabel:document.querySelector('#contextLabel'),toast:document.querySelector('#toast'),complexGrid:document.querySelector('#complexGrid'),complexCount:document.querySelector('#complexCount'),complexRegionTitle:document.querySelector('#complexRegionTitle'),complexSummary:document.querySelector('#complexSummary'),complexSearch:document.querySelector('#complexSearch')};
let currentDeal='sale';
function renderChart(values){if(values.length===1)values=[values[0],values[0]];const w=600,h=160,p=12,min=Math.min(...values)-2,max=Math.max(...values)+2;const pts=values.map((v,i)=>[p+i*(w-p*2)/(values.length-1),h-p-(v-min)*(h-p*2)/(max-min)]);const poly=pts.map(p=>p.join(',')).join(' ');const area=`${p},${h-p} ${poly} ${w-p},${h-p}`;els.indexChart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f26d67" stop-opacity=".22"/><stop offset="1" stop-color="#f26d67" stop-opacity="0"/></linearGradient></defs>${[30,70,110,150].map(y=>`<line class="chart-gridline" x1="0" y1="${y}" x2="600" y2="${y}"/>`).join('')}<polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${poly}"/>${pts.map((p,i)=>`<circle class="chart-dot ${i===pts.length-1?'current':''}" cx="${p[0]}" cy="${p[1]}" r="${i===pts.length-1?5:3}"/>`).join('')}</svg>`}
function renderBars(values){const max=Math.max(...values);els.volumeChart.innerHTML=values.map(v=>{const h=Math.round(v/max*100);return `<div class="bar-wrap" data-value="${v}건" style="--h:${h}%"><i style="height:${h}%"></i></div>`}).join('')}
function displayDate(value){return value?value.replaceAll('-','.'):'계약일 미상'}
function renderRank(target,data){if(!data.length){target.innerHTML='<p style="padding:28px 4px;color:#858c88;font-size:12px">선택한 지역의 TOP 10 표본은 아직 없습니다. 위 단지 목록에서 해당 지역의 아파트를 확인하세요.</p>';return}const nums=data.map(x=>parseFloat(String(x[2]).replace(/,/g,''))) ;const max=Math.max(...nums);target.innerHTML=data.map((r,i)=>`<div class="rank-row"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="rank-name"><strong>${r[0]}</strong><small>${r[1]}</small></span><span class="rank-bar"><i style="width:${Math.max(18,nums[i]/max*100)}%"></i></span><span class="rank-price">${r[2]}</span></div>`).join('')}
function pct(current,previous){if(!previous)return '-';const value=(current/previous-1)*100;return `${value>=0?'+':''}${value.toFixed(1)}%`}
function trend(value){return value.startsWith('-')?'down':value==='-'?'flat':'up'}
function selectedRegionName(){const select=document.querySelector('#regionSelect');return select.options[select.selectedIndex].text}
function updateRankings(){const d=datasets[currentDeal],region=document.querySelector('#regionSelect').value;const filter=rows=>rows.filter(row=>region==='all'||row[1].includes(region));const trade=filter(d.trade),unit=filter(d.unit),name=selectedRegionName();els.tradeRankTitle.textContent=region==='all'?d.tradeTitle:`${name} 주요 ${d.label}`;els.unitRankTitle.textContent=region==='all'?d.unitTitle:`${name} 평당가`;renderRank(els.tradeRank,trade);renderRank(els.unitRank,unit)}
function renderComplexes(){const region=document.querySelector('#regionSelect').value,name=selectedRegionName(),query=els.complexSearch.value.trim().toLowerCase();const catalog=window.GYEONGJU_COMPLEXES||{};let rows=region==='all'?Object.entries(catalog).flatMap(([area,items])=>items.map(item=>[...item,area])):(catalog[region]||[]).map(item=>[...item,name]);rows=rows.filter(row=>!query||row.slice(0,3).join(' ').toLowerCase().includes(query));els.complexRegionTitle.textContent=name;els.complexCount.textContent=rows.length;els.complexSummary.textContent=region==='all'?'경주시 읍·면·동에서 확인된 대표 단지를 모았습니다. 지역을 선택하면 더 빠르게 볼 수 있습니다.':`${name}에서 확인된 대표 단지입니다. 단지명을 눌러 시세와 실거래를 확인하세요.`;if(!rows.length){els.complexGrid.innerHTML=`<div class="complex-empty"><strong>${query?'검색 결과가 없습니다.':'현재 확인된 대표 단지 자료가 없습니다.'}</strong><p>${query?'다른 단지명으로 검색해 보세요.':'이 표시는 아파트가 없다는 뜻이 아닙니다. 아래 공식 원문에서 주소·단지명을 추가 확인해 주세요.'}</p><a href="https://rt.molit.go.kr/" target="_blank" rel="noreferrer">국토교통부 실거래가 원문 보기 →</a></div>`;return}els.complexGrid.innerHTML=rows.map((r,i)=>`<a class="complex-card" href="${r[3]}" target="_blank" rel="noreferrer"><span class="complex-index">${String(i+1).padStart(2,'0')}</span><div><strong>${r[0]}</strong><p>${r[4]} · ${r[1]}</p><small>${r[2]}</small></div><b>↗</b></a>`).join('')}
function setDateRange(key){const start=document.querySelector('#startDate'),end=document.querySelector('#endDate'),latest=snapshotSeries[key].at(-1).key,limits=availability[key];start.min=end.min=limits.min;start.max=end.max=limits.max;start.value=`${latest}-01`;end.value=limits.max}
function snapshotKpis(snapshot,previous){const volumeDelta=pct(snapshot.volume,previous?.volume);if(currentDeal==='sale'){const avgDelta=pct(snapshot.avg,previous?.avg),medianDelta=pct(snapshot.median,previous?.median),unitDelta=pct(snapshot.unit,previous?.unit);return [['월간 거래건수',String(snapshot.volume),'건',volumeDelta,'전월 대비',trend(volumeDelta)],['월간 평균 거래가',snapshot.avg.toFixed(2),'억원',avgDelta,'전월 대비',trend(avgDelta)],['월간 중위 거래가',snapshot.median.toFixed(2),'억원',medianDelta,'전월 대비',trend(medianDelta)],['월간 평균 3.3㎡당',snapshot.unit.toLocaleString(),'만원',unitDelta,'전월 대비',trend(unitDelta)]]}if(currentDeal==='jeonse'){const avgDelta=pct(snapshot.avg,previous?.avg);return [['월간 전세 계약',String(snapshot.volume),'건',volumeDelta,'전월 대비',trend(volumeDelta)],['월간 평균 보증금',snapshot.avg.toFixed(2),'억원',avgDelta,'전월 대비',trend(avgDelta)],['월간 중위 보증금',snapshot.median.toFixed(2),'억원','월 집계','계약 표본','flat'],['60~85㎡ 월평균',snapshot.sizeAvg.toFixed(2),'억원','면적 보정','계약 표본','flat']]}const rentDelta=pct(snapshot.rent,previous?.rent);return [['월간 월세 계약',String(snapshot.volume),'건',volumeDelta,'전월 대비',trend(volumeDelta)],['월간 평균 보증금',snapshot.deposit.toLocaleString(),'만원','월 집계','월세 계약','flat'],['월간 평균 월세',String(snapshot.rent),'만원',rentDelta,'전월 대비',trend(rentDelta)],['월간 월세 비중',String(snapshot.share),'%','임대차 중','공개 집계','flat']]}
function rangeLabel(){const start=document.querySelector('#startDate').value,end=document.querySelector('#endDate').value;if(!start||!end)return '';return start===end?displayDate(start):`${displayDate(start)}–${displayDate(end)}`}
function renderSnapshot(){const d=datasets[currentDeal],series=snapshotSeries[currentDeal],end=document.querySelector('#endDate').value,selectedMonth=end.slice(0,7);let index=series.findIndex(s=>s.key===selectedMonth);if(index<0){index=series.findLastIndex(s=>s.key<selectedMonth);if(index<0)index=0}const snapshot=series[index],previous=series[index-1],kpis=snapshotKpis(snapshot,previous),volumeDelta=pct(snapshot.volume,previous?.volume);els.asOf.textContent=snapshot.key.replace('-', '. ');document.querySelector('.asof small').textContent=`종료일 기준 ${d.asOfSub}`;els.marketSummary.textContent=`${rangeLabel()} 거래 표본을 조회 중입니다. 상단 지표와 거래량은 종료일이 속한 ${snapshot.label} 월간 집계입니다.`;els.kpiGrid.innerHTML=kpis.map((k,i)=>`<article class="kpi" style="--kpi-color:${['#ffe0dc','#dceef2','#e5eccf','#eee4d6'][i]}"><span class="kpi-label">${k[0]}</span><div class="kpi-value"><strong>${k[1]}</strong><span>${k[2]}</span></div><div class="kpi-meta"><b class="${k[5]}">${k[3]}</b>${k[4]}</div></article>`).join('');els.volumeTitle.textContent=`월별 ${d.label} 거래량`;els.volumeBadge.textContent=`전월 ${volumeDelta}`;els.volumeBadge.style.background=volumeDelta.startsWith('-')?'var(--blue-soft)':'var(--coral-soft)';els.volumeBadge.style.color=volumeDelta.startsWith('-')?'#2788ad':'#c94d48';els.volumeValue.textContent=snapshot.volume;els.volumeSub.textContent=`${snapshot.label} 전체`;els.volumeNote.innerHTML=`<span>월간</span> ${d.volumeNote}`;renderBars(series.slice(Math.max(0,index-7),index+1).map(s=>s.volume));updateContext()}
function renderDeal(key,announce=false){currentDeal=key;const d=datasets[key];setDateRange(key);els.tradeRankUnit.textContent=d.tradeUnit;els.unitRankUnit.textContent=d.unitUnit;updateRankings();renderSnapshot();document.querySelectorAll('[data-deal]').forEach(btn=>{const active=btn.dataset.deal===key;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});if(announce)showToast(`${d.label} 최신 공개기간을 달력에 불러왔습니다.`)}
function updateContext(){const region=document.querySelector('#regionSelect').value,name=selectedRegionName(),period=rangeLabel();els.contextLabel.textContent=region==='all'?`${name} · ${datasets[currentDeal].label} · ${period}`:`${name} · ${datasets[currentDeal].label} · ${period} (상단 월간 지표는 경주시 전체)`}
function renderLocation(key){const d=locationData[key];document.querySelector('#detailKicker').textContent=d.kicker;document.querySelector('#detailTitle').textContent=d.title;document.querySelector('#detailScore').textContent=d.score;document.querySelector('#detailSummary').textContent=d.summary;document.querySelector('#areaChips').innerHTML=d.areas.map(x=>`<span>${x}</span>`).join('');document.querySelector('#scoreBars').innerHTML=d.bars.map(x=>`<div class="score-row"><span>${x[0]}</span><div><i style="width:${x[1]}%"></i></div><b>${x[1]}</b></div>`).join('');document.querySelector('#detailBullets').innerHTML=d.bullets.map(x=>`<li>${x}</li>`).join('');document.querySelector('#detailCaution').textContent=d.caution;document.querySelectorAll('.location-tab').forEach(btn=>{const active=btn.dataset.location===key;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active))})}
let toastTimer;function showToast(msg){clearTimeout(toastTimer);els.toast.textContent=msg;els.toast.classList.add('show');toastTimer=setTimeout(()=>els.toast.classList.remove('show'),2200)}
document.querySelectorAll('[data-deal]').forEach(btn=>btn.addEventListener('click',()=>renderDeal(btn.dataset.deal,true)));
document.querySelectorAll('.location-tab').forEach(btn=>btn.addEventListener('click',()=>renderLocation(btn.dataset.location)));
document.querySelector('#regionSelect').addEventListener('change',e=>{els.complexSearch.value='';updateContext();updateRankings();renderComplexes();document.querySelector('#complexes').scrollIntoView({behavior:'smooth',block:'start'});showToast(e.target.value==='all'?'경주시 전체 단지로 돌아왔습니다.':`${selectedRegionName()} 아파트 단지를 표시합니다.`)});
function handleDateChange(changed){const start=document.querySelector('#startDate'),end=document.querySelector('#endDate');if(start.value>end.value){if(changed==='start')end.value=start.value;else start.value=end.value}renderSnapshot();showToast(`${end.value.slice(0,7).replace('-','년 ')}월 월간 집계로 조회했습니다.`)}
document.querySelector('#startDate').addEventListener('change',()=>handleDateChange('start'));
document.querySelector('#endDate').addEventListener('change',()=>handleDateChange('end'));
els.complexSearch.addEventListener('input',renderComplexes);
document.querySelector('#resetBtn').addEventListener('click',()=>{document.querySelector('#regionSelect').value='all';els.complexSearch.value='';renderDeal('sale');renderComplexes();showToast('경주시 전체·최신 매매기간으로 초기화했습니다.')});
const methodPanel=document.querySelector('#methodPanel');function toggleMethod(show){methodPanel.hidden=!show;document.querySelector('#methodBtn').setAttribute('aria-expanded',String(show))}document.querySelector('#methodBtn').addEventListener('click',()=>toggleMethod(methodPanel.hidden));document.querySelector('#closeMethod').addEventListener('click',()=>toggleMethod(false));document.querySelector('#closeMethodLink').addEventListener('click',()=>toggleMethod(false));
const sections=[...document.querySelectorAll('main section[id]')];const navLinks=[...document.querySelectorAll('.nav a')];const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${entry.target.id}`))}}),{rootMargin:'-45% 0px -50%'});sections.forEach(s=>observer.observe(s));
renderDeal('sale');renderLocation('school');renderComplexes();
